// Loc san pham hidden=true (thieu anh that/chua san sang) khoi toan bo trang
// khach hang - moi noi import { products } deu tu dong loc, khong can sua rieng.
export const products: Product[] = allProducts.filter((p) => !p.hidden);

export function getProductsByType(id: ProductTypeId): Product[] {
  return products.filter((p) => p.productType === id);
}

const VND_PER_USD = 25000;

export interface CartCompatibleProduct {
  id: string;
  name: string;
  nameVi: string;
  category: string;
  healthGoal: HealthGoal;
  audiences: TargetAudience[];
  priceUSD: number;
  priceVND: number;
  priceJPY: number;
  priceCNY: number;
  priceEUR: number;
  activeIngredient: string;
  description: string;
  descriptionVi: string;
  image: string;
  badge: string;
  rating: number;
  reviews: number;
  familySafe?: boolean;
}

export function toCartProduct(p: Product): CartCompatibleProduct {
  const price = p.price ?? 0;
  const priceUSD = Math.round((price / VND_PER_USD) * 100) / 100;
  return {
    id: p.sku,
    name: p.name,
    nameVi: p.name,
    category: p.productType,
    healthGoal: p.healthGoal,
    audiences: p.audiences,
    priceUSD,
    priceVND: price,
    priceJPY: Math.round(priceUSD * 150),
    priceCNY: Math.round(priceUSD * 7.2 * 100) / 100,
    priceEUR: Math.round(priceUSD * 0.93 * 100) / 100,
    activeIngredient: p.activeIngredient ?? '',
    description: p.description,
    descriptionVi: p.description,
    image: p.image,
    badge: p.badge ?? '',
    rating: 0,
    reviews: 0,
    familySafe: p.familySafe,
  };
}
